 "content": "def transform(grid):
    g = [row[:] for row in grid]
    # The patterned object and blank target are equal-sized rectangles;
    # copy the pattern into the blank area, retaining its orientation.
    bg = max({v for row in g for v in row}, key=lambda v: sum(row.count(v) for row in g))
    counts = {}
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v != bg:
                counts[v] = counts.get(v, 0) + 1
    # Target is the largest connected rectangle of a single non-background color
    # (color zero in these tasks); source is the other patterned rectangle.
    target_color = max(counts, key=counts.get)
    target = [(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v == target_color]
    tr0,tc0 = min(r for r,c in target), min(c for r,c in target)
    tr1,tc1 = max(r for r,c in target), max(c for r,c in target)
    h,w = tr1-tr0+1,tc1-tc0+1
    source = [(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v not in (bg,target_color)]
    sr0,sc0 = min(r for r,c in source), min(c for r,c in source)
    # Source pattern is the non-background region's bounding rectangle.
    for i in range(h):
        for j in range(w):
            g[tr0+i][tc0+j] = grid[sr0+i][sc0+j]
    return g
